import sys
try:
    import pysat
    print("pysat available")
except:
    print("pysat not available")
try:
    import networkx as nx
    print("networkx available")
except:
    print("networkx not available")

from pysat.solvers import Solver
from pysat.card import CardEnc
import itertools

n = 14
var_map = {}
var_idx = 1
for u in range(n):
    for v in range(u+1, n):
        var_map[(u,v)] = var_idx
        var_idx += 1

fixed_edges = [(4,5), (0,10), (2,7), (6,8), (2,8), (1,6), (0,9), (5,8)]

# Let's try with different solver
for solver_name in ['glucose4', 'glucose3', 'minisat22', 'cadical153']:
    try:
        solver = Solver(name=solver_name)
        for (u,v) in fixed_edges:
            solver.add_clause([var_map[(u,v)]])

        for v in range(n):
            incident_vars = []
            for u in range(n):
                if u < v:
                    incident_vars.append(var_map[(u,v)])
                elif u > v:
                    incident_vars.append(var_map[(v,u)])
            c = CardEnc.atleast(lits=incident_vars, bound=3, top_id=var_idx-1, encoding=1)
            for clause in c.clauses:
                solver.add_clause(clause)
            c = CardEnc.atmost(lits=incident_vars, bound=6, top_id=var_idx-1, encoding=1)
            for clause in c.clauses:
                solver.add_clause(clause)

        status = solver.solve()
        print(f"{solver_name}: {status}")
        if status:
            model = solver.get_model()
            edges = []
            for (u,v), idx in var_map.items():
                if model[idx-1] > 0:
                    edges.append((u,v))
            print(f"Edges: {len(edges)}")
            deg = [0]*n
            for u,v in edges:
                deg[u] += 1
                deg[v] += 1
            print("Degrees:", deg)
            break
    except Exception as e:
        print(f"{solver_name}: error {e}")
